```ts
export function normalizeRepoUrl(url: string): string {
  let u = url.trim()
  if (/^[a-z][a-z0-9+.-]*:\/\//i.test(u)) {
    const m = u.match(/^(https?:\/\/)([^/]+)(\/.*)?$/i)!
    u = m[1] + m[2].toLowerCase() + (m[3] ?? '')
  }
  u = u.replace(/\/+$/, '')
  if (u.endsWith('.git')) u = u.slice(0, -4)
  return u
}
```

