async updateStatus(jobId, input) {
  try {
    const res = await client.callTool({ name: 'update_job_status', arguments: { job_id: jobId, ...input } })
    if (res.isError) return { ok: false, message: text(res) }
    const body = text(res)
    let p: { status?: unknown; branch?: unknown; pushed_at?: unknown; error?: unknown } = {}
    try { p = JSON.parse(body) } catch { p = {} }
    const out: StatusOutcome = { ok: true }
    if (typeof p.status === 'string' && ['running','done','failed','skipped'].includes(p.status)) out.status = p.status
    if (typeof p.branch === 'string') out.branch = p.branch
    if (typeof p.pushed_at === 'string') out.pushedAt = p.pushed_at
    if (typeof p.error === 'string') out.error = p.error
    return out
  } catch (err) {
    return { ok: false, message: message(err) }
  }
}
