async verifyTaskAgainstPlan(taskId, worktreePath) {
  const res = await client.callTool({ name: 'verify_task_against_plan', arguments: { task_id: taskId, worktree_path: worktreePath } })
  if (res.isError) return { ok: false, message: text(res) }
  const body = text(res)
  let result: unknown
  try {
    const p = JSON.parse(body) as { result?: unknown }
    result = p?.result
  } catch {
    result = body
  }
  const mapped = typeof result === 'string' ? (result.toLowerCase() as VerifyResult) : undefined
  if (mapped && ['aligned','partial','empty','divergent'].includes(mapped)) return { ok: true, result: mapped }
