```ts
export function normalizeRepoUrl(url: string): string {
  let u = url.trim()
  // lowercase the host
  u = u.replace(/^([a-zA-Z+][a-zA-Z0-9+.-]*:\/\/)([^/]+)/, (m, scheme, host) => `${scheme}${host.toLowerCase()}`)
  // also handle scp-style? probably not needed
  u = u.replace(/\/+$/, '')
  u = u.replace(/\.git$/, '')
  return u
}
```

