    const p = parsed as { result?: unknown; message?: unknown }
    const result = typeof p.result === 'string' ? p.result.toLowerCase() : undefined
    const known = ['aligned','partial','empty','divergent']
    return { ok: true, ...(result && known.includes(result) ? { result: result as ... } : {}), ...(typeof p.message === 'string' ? { message: p.message } : {}) }
  } catch (err) { return { ok: false, message: message(err) } }
}
