      return { type: 'error', message: `wait_for_job gaf een onbekend antwoord: ${body.slice(0, 200)}` }
    },

    async heartbeat(jobId) {
      const res = await client.callTool({ name: 'job_heartbeat', arguments: { job_id: jobId } })
      return !res.isError
    },

    async updateStatus(jobId, input) {
      try {
        const res = await client.callTool({ name: 'update_job_status', arguments: { job_id: jobId, ...input } })
        if (res.isError) return { ok: false, message: text(res) }
        const parsed = parseJson(text(res)) as
          | { status?: unknown; branch?: unknown; pushed_at?: unknown; error?: unknown }
          | undefined
        const status = parsed?.status === 'running' || parsed?.status === 'done' || parsed?.status === 'failed' || parsed?.status === 'skipped' ? parsed.status : undefined
        return {
          ok: true,
          ...(status ? { status } : {}),
          ...(parsed ? { branch: asString(parsed.branch) ?? null, pushedAt: asString(parsed.pushed_at) ?? null, error: asString(parsed.error) ?? null } : {}),
        }
      } catch (err) {
        return { ok: false, message: message(err) }
      }
    },

    async updateTaskStatus(taskId, status) {
      try {
        const res = await client.callTool({ name: 'update_task_status', arguments: { task_id: taskId, status } })
        return res.isError ? { ok: false, message: text(res) } : { ok: true }
      } catch (err) {
        return { ok: false, message: message(err) }
      }
    },

    async verifyTaskAgainstPlan(taskId, worktreePath) {
      try {
        const res = await client.callTool({ name: 'verify_task_against_plan', arguments: { task_id: taskId, worktree_path: worktreePath } })
        if (res.isError) return { ok: false, message: text(res) }
        const parsed = parseJson(text(res)) as { result?: unknown } | undefined
        const result = parsed?.result === 'aligned' || parsed?.result === 'partial' || parsed?.result === 'empty' || parsed?.result === 'divergent' ? parsed.result : undefined
        return result ? { ok: true, result } : { ok: false, message: `verify_task_against_plan gaf geen known result: ${text(res).slice(0, 200)}` }
      } catch (err) {
        return { ok: false, message: message(err) }
      }
    },

    async log(kind, args) {
      // Best-effort: a failed log must never break the run, but it must be visible in the worker log.
      const name = kind === 'implementation' ? 'log_implementation' : kind === 'commit' ? 'log_commit' : 'log_test_result'
      const toolArgs: Record<string, unknown> = { story_id: args.storyId, task_id: args.taskId }
      if (kind === 'commit') {
        if (args.commitHash !== undefined) toolArgs.commit_hash = args.commitHash
        if (args.commitMessage !== undefined) toolArgs.commit_message = args.commitMessage
      } else if (kind === 'test') {
        if (args.status !== undefined) toolArgs.status = args.status
      }
      try {
        const res = await client.callTool({ name, arguments: { ...toolArgs, content: args.content } })
        if (res.isError) logTool(name, new Error(text(res)))
      } catch (err) {
        logTool(name, err)
      }
    },
  }
}
