import { InMemoryTransport } from '@modelcontextprotocol/sdk/inMemory.js'
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js'
import { z } from 'zod'

/** One wait_for_job answer: a timeout, a claimed job payload, a tool error, or a handler that keeps waiting. */
export type ClaimStep = { timeout: true } | { job: unknown } | { error: string } | { hangMs: number }

export type ToolCallRecord = { name: string; args: Record<string, unknown> }

const toolText = (value: unknown) => ({ content: [{ type: 'text' as const, text: JSON.stringify(value) }] })
const toolError = (message: string) => ({ isError: true, content: [{ type: 'text' as const, text: message }] })

export type VerifyResult = 'aligned' | 'partial' | 'empty' | 'divergent'

export type FakeMcpOptions = {
  claims?: ClaimStep[]
  failUpdate?: Array<'running' | 'done' | 'failed'>
  /** When given, a `done` update is answered with `{ status: 'failed', error }` (the push failed server-side), not an isError. */
  updateOutcome?: { status: 'failed'; error?: string }
  verifyResult?: VerifyResult
  failVerify?: boolean
}

/**
 * In-process stand-in for the scrum4me MCP: the control tools (wait_for_job, job_heartbeat,
 * update_job_status, update_task_status, verify_task_against_plan, log_implementation,
 * log_commit, log_test_result) plus the four doc tools. `calls` records every call the server
 * received. Exhausted claim scripts answer with a timeout.
 */
export async function startFakeScrum4meMcp(opts: FakeMcpOptions = {}) {
  const calls: ToolCallRecord[] = []
  const claims = [...(opts.claims ?? [])]
  const state = {
    heartbeatOk: true,
    failUpdate: new Set(opts.failUpdate ?? []),
    verifyResult: (opts.verifyResult ?? 'aligned') as VerifyResult,
    failVerify: opts.failVerify ?? false,
    doneSeen: false,
  }
  const server = new McpServer({ name: 'fake-scrum4me', version: '0.0.0' })

  server.registerTool('wait_for_job', { inputSchema: { wait_seconds: z.number().int().optional() } }, async (args) => {
    calls.push({ name: 'wait_for_job', args })
    const step = claims.shift() ?? { timeout: true }
    if ('hangMs' in step) {
      await new Promise((r) => setTimeout(r, step.hangMs))
      return toolText({ status: 'timeout', message: 'No job available within wait window' })
    }
    if ('error' in step) return toolError(step.error)
    if ('job' in step) return toolText(step.job)
    return toolText({ status: 'timeout', message: 'No job available within wait window' })
  })
  server.registerTool('job_heartbeat', { inputSchema: { job_id: z.string() } }, async (args) => {
    calls.push({ name: 'job_heartbeat', args })
    if (!state.heartbeatOk) return toolError(`Job ${args.job_id} not found, not claimed by your token, or in terminal state`)
    return toolText({ ok: true, job_id: args.job_id })
  })
  server.registerTool(
    'update_job_status',
    {
      inputSchema: {
        job_id: z.string(),
        status: z.enum(['running', 'done', 'failed', 'skipped']),
        summary: z.string().max(4000).optional(),
        error: z.string().max(2000).optional(),
        model_id: z.string().optional(),
        input_tokens: z.number().int().optional(),
        output_tokens: z.number().int().optional(),
      },
    },
    async (args) => {
      calls.push({ name: 'update_job_status', args })
      if (state.failUpdate.has(args.status as 'running' | 'done' | 'failed')) return toolError(`Job ${args.job_id} is already terminal`)
      // The real MCP answers with the actual outcome, not a bare ok: what status landed,
      // and (for done) the pushed branch and when.
      const base = { ok: true, status: args.status }
      if (args.status === 'done') {
        if (opts.updateOutcome) {
          state.doneSeen = true
          return toolText({ ok: true, status: 'failed', branch: null, pushed_at: null, error: opts.updateOutcome.error ?? 'push failed' })
        }
        state.doneSeen = true
        return toolText({ ...base, branch: `feat/harness-${args.job_id}`, pushed_at: '2026-09-27T12:00:00.000Z' })
      }
      return toolText(base)
    },
  )
  server.registerTool('update_task_status', { inputSchema: { task_id: z.string(), status: z.enum(['todo', 'in_progress', 'review']) } }, async (args) => {
    calls.push({ name: 'update_task_status', args })
    return toolText({ ok: true, task_id: args.task_id, status: args.status })
  })
  server.registerTool(
    'verify_task_against_plan',
    { inputSchema: { task_id: z.string(), worktree_path: z.string() } },
    async (args) => {
      calls.push({ name: 'verify_task_against_plan', args })
      if (state.failVerify) return toolError(`verify_task_against_plan mislukt voor taak ${args.task_id}`)
      return toolText({ ok: true, task_id: args.task_id, result: state.verifyResult })
    },
  )
  server.registerTool(
    'log_implementation',
    { inputSchema: { story_id: z.string(), task_id: z.string(), content: z.string() } },
    async (args) => {
      calls.push({ name: 'log_implementation', args })
      return toolText({ ok: true, task_id: args.task_id })
    },
  )
  server.registerTool(
    'log_commit',
    { inputSchema: { story_id: z.string(), task_id: z.string(), content: z.string(), commit_hash: z.string().optional(), commit_message: z.string().optional() } },
    async (args) => {
      calls.push({ name: 'log_commit', args })
      return toolText({ ok: true, task_id: args.task_id })
    },
  )
  server.registerTool(
    'log_test_result',
    { inputSchema: { story_id: z.string(), task_id: z.string(), content: z.string(), status: z.enum(['PASSED', 'FAILED']).optional() } },
    async (args) => {
      calls.push({ name: 'log_test_result', args })
      return toolText({ ok: true, task_id: args.task_id })
    },
  )
  server.registerTool('search_product_docs', { description: 'Search product docs', inputSchema: { product_id: z.string(), query: z.string() } }, async (args) => {
    calls.push({ name: 'search_product_docs', args })
    return toolText({ results: [{ doc_id: 'doc1', title: 'Worker-runbook', product_id: args.product_id }] })
  })
  server.registerTool('get_product_doc', { description: 'Read one product doc', inputSchema: { doc_id: z.string() } }, async (args) => {
    calls.push({ name: 'get_product_doc', args })
    return toolText({ doc_id: args.doc_id, content_md: '# Worker-runbook' })
  })
  server.registerTool('list_product_docs', { description: 'List product docs', inputSchema: { product_id: z.string() } }, async (args) => {
    calls.push({ name: 'list_product_docs', args })
    return toolText({ docs: [] })
  })
  server.registerTool('related_product_docs', { description: 'Related product docs', inputSchema: { doc_id: z.string() } }, async (args) => {
    calls.push({ name: 'related_product_docs', args })
    return toolText({ related: [] })
  })

  const [clientTransport, serverTransport] = InMemoryTransport.createLinkedPair()
  await server.connect(serverTransport)
  const client = new Client({ name: 'harness-worker-test', version: '0.0.0' })
  await client.connect(clientTransport)
  return {
    client,
    calls,
    state,
    close: async () => {
      await client.close().catch(() => undefined)
      await server.close().catch(() => undefined)
    },
  }
}
