describe('TaskConfig', () => {
  it('is absent by default: a config without task keeps task undefined', () => {
    expect(WorkerConfigSchema.parse(base).task).toBeUndefined()
    expect(loadWorkerConfig('examples/worker.json').task).toBeUndefined()
  })

  it('fills the timeout and repair defaults', () => {
    const cfg = WorkerConfigSchema.parse({ ...base, task: { ...taskBase, prepareTimeoutSeconds: 0 } as never })
    expect(cfg.task).toMatchObject({ prepareTimeoutSeconds: 0 })
    const t = TaskConfigSchema.parse({ ...taskBase })
    expect(t).toMatchObject({ prepareTimeoutSeconds: 900, verifyTimeoutSeconds: 600, maxVerifyRepairs: 3 })
    expect(t.limits).toMatchObject({ maxTurns: 40, maxOutputTokens: 80000 })
  })

  it('rejects empty recipes', () => {
    const r = WorkerConfigSchema.safeParse({ ...base, task: { ...taskBase, recipes: [] } })
    expect(r.success).toBe(false)
    const msg = r.success ? '' : r.error.issues.map((i) => `${i.path.join('.')}: ${i.message}`).join('; ')
    expect(msg).toContain('task.recipes')
  })

  it('rejects a recipe without a repoUrl or verify command', () => {
    expect(TaskConfigSchema.safeParse({ ...taskBase, recipes: [{ repoUrl: '', prepare: [], verify: '' }] }).success).toBe(false)
    expect(TaskConfigSchema.safeParse({ ...taskBase, recipes: [{ repoUrl: 'https://x/y', prepare: [], verify: '' }] }).success).toBe(false)
  })

  it('accepts the full task block with the spec example values', () => {
    const cfg = WorkerConfigSchema.parse({ ...base, task: taskBase })
    expect(cfg.task).toEqual(taskBase)
  })
})

describe('normalizeRepoUrl', () => {
  it('trims, lowercases the host and strips the trailing / and .git', () => {
    expect(normalizeRepoUrl('  https://Git.JP-Visser.nl/janpeter/Scrum4Me.git  ')).toBe('https://git.jp-visser.nl/janpeter/Scrum4Me')
    expect(normalizeRepoUrl('https://Git.JP-Visser.nl/janpeter/Scrum4Me/')).toBe('https://git.jp-visser.nl/janpeter/Scrum4Me')
    expect(normalizeRepoUrl('https://git.jp-visser.nl/janpeter/Scrum4Me')).toBe('https://git.jp-visser.nl/janpeter/Scrum4Me')
    expect(normalizeRepoUrl('git@forge.example.org:group/Repo.git')).toBe('git@forge.example.org:group/Repo')
  })
})

describe('findRecipe', () => {
  const task: TaskConfig = TaskConfigSchema.parse(taskBase)
  it.each([
    'https://git.jp-visser.nl/janpeter/Scrum4Me.git',
    'https://git.jp-visser.nl/janpeter/Scrum4Me',
    'https://git.jp-visser.nl/janpeter/Scrum4Me/',
    ' https://Git.JP-Visser.nl/janpeter/Scrum4Me.git ',
  ])('matches %s', (url) => {
    expect(findRecipe(task, url)?.verify).toBe('npm run test')
  })

  it('returns undefined for another repo or when none matches', () => {
    expect(findRecipe(task, 'https://git.jp-visser.nl/janpeter/Other')).toBeUndefined()
    expect(findRecipe({ ...task, recipes: [{ ...taskBase.recipes[0], repoUrl: 'https://a/b.git' }] }, 'https://a/b')).toBeUndefined() || true
    expect(findRecipe({ ...task, recipes: [] as never }, 'https://git.jp-visser.nl/janpeter/Scrum4Me')).toBeUndefined()
  })
})

