    mcp = await startFakeScrum4meMcp({ claims: [job()] })
    const r = await createControlChannel(mcp.client).waitForJob(1, new AbortController().signal)
    expect(r).toMatchObject({ type: 'job', jobId: 'job1', kind: 'IDEA_CHAT' })
  })

  it('parses a done answer into status, branch and pushedAt; a non-error answer is not an error', async () => {
    mcp = await startFakeScrum4meMcp()
    const control = createControlChannel(mcp.client)
    const r = await control.updateStatus('job1', { status: 'done', summary: 'klaar' })
    expect(r).toEqual({ ok: true, status: 'done', branch: 'feat/harness-job1', pushedAt: '2026-09-27T12:00:00.000Z', error: null })
  })

  it('reports a server-side failure with status failed and the error from the JSON answer, without isError', async () => {
    mcp = await startFakeScrum4meMcp({ updateOutcome: { status: 'failed', error: 'push failed' } })
    const control = createControlChannel(mcp.client)
    const r = await control.updateStatus('job1', { status: 'done', summary: 'klaar' })
    expect(r).toEqual({ ok: true, status: 'failed', branch: null, pushedAt: null, error: 'push failed' })
  })

  it('still maps a bare ok answer and a server tool error to ok false with a message', async () => {
    mcp = await startFakeScrum4meMcp({ failUpdate: ['done'] })
    const control = createControlChannel(mcp.client)
    expect(await control.updateStatus('job1', { status: 'running' })).toEqual({ ok: true, status: 'running' })
    expect(await control.updateStatus('job1', { status: 'done' })).toEqual({ ok: false, message: 'Job job1 is already terminal' })
  })

  it('sends update_task_status, verify_task_against_plan and the log tools with the right argument names', async () => {
    mcp = await startFakeScrum4meMcp()
    const control = createControlChannel(mcp.client)
    await control.updateTaskStatus('task1', 'in_progress')
    expect(await control.updateTaskStatus('task1', 'review')).toEqual({ ok: true })
    expect(await control.verifyTaskAgainstPlan('task1', '/srv/claude/scrums/s1/stories/st1/worktrees/wt1')).toEqual({ ok: true, result: 'aligned' })
    await control.log('implementation', { storyId: 'story1', taskId: 'task1', content: 'start' })
    await control.log('commit', { storyId: 'story1', taskId: 'task1', content: 'commit', commitHash: 'abc123', commitMessage: 'Taak 7' })
    await control.log('test', { storyId: 'story1', taskId: 'task1', content: 'groen', status: 'PASSED' })
    expect(mcp.calls.filter((c) => c.name === 'update_task_status').map((c) => c.args)).toEqual([
      { task_id: 'task1', status: 'in_progress' },
      { task_id: 'task1', status: 'review' },
    ])
    expect(mcp.calls.filter((c) => c.name === 'verify_task_against_plan').map((c) => c.args)).toEqual([
      { task_id: 'task1', worktree_path: '/srv/claude/scrums/s1/stories/st1/worktrees/wt1' },
    ])
    expect(mcp.calls.filter((c) => c.name === 'log_implementation').map((c) => c.args)).toEqual([{ story_id: 'story1', task_id: 'task1', content: 'start' }])
    expect(mcp.calls.filter((c) => c.name === 'log_commit').map((c) => c.args)).toEqual([
      { story_id: 'story1', task_id: 'task1', commit_hash: 'abc123', commit_message: 'Taak 7', content: 'commit' },
    ])
    expect(mcp.calls.filter((c) => c.name === 'log_test_result').map((c) => c.args)).toEqual([{ story_id: 'story1', task_id: 'task1', status: 'PASSED', content: 'groen' }])
  })

  it('reports verify_task_against_plan outcomes and errors', async () => {
    mcp = await startFakeScrum4meMcp({ verifyResult: 'divergent' })
    expect(await createControlChannel(mcp.client).verifyTaskAgainstPlan('task1', '/wt')).toEqual({ ok: true, result: 'divergent' })
    mcp = await startFakeScrum4meMcp({ failVerify: true })
    expect(await createControlChannel(mcp.client).verifyTaskAgainstPlan('task1', '/wt')).toMatchObject({ ok: false, message: expect.stringMatching(/mislukt/) })
  })

  it('logs a failed log tool as best effort without throwing', async () => {
    mcp = await startFakeScrum4meMcp()
    const control = createControlChannel(mcp.client)
    vi.spyOn(mcp.client, 'callTool').mockRejectedValueOnce(new Error('weg'))
    await expect(control.log('implementation', { storyId: 's', taskId: 't', content: 'x' })).resolves.toBeUndefined()
  })
})"}

